SELECT tblCase.*, qryTrustAccount.SumOfDebit, qryTrustAccount.SumOfCredit, qryTrustAccount.Balance, qryStmtTrustRPT.TrustAccountID, qryStmtTrustRPT.TDate, qryStmtTrustRPT.TMatter, qryStmtTrustRPT.Debit, qryStmtTrustRPT.Credit, qryStmtTrustRPT.CheckNumber, qryStmtTrustRPT.[Case No], qryStmtTrustRPT.CheckCashed, qryStmtTrustRPT.DepCleared, qryStmtTrustRPT.Reconciled, qryTrustAccount.OrderNr, [tblcase.Last_Name] & ", " & [tblcase.First_Name] AS Name, Replace([tblcase.Case_Letter] & [tblcase.yr] & "-" & [tblcase.Number_] & "-" & [tblcase.Orig_Atty],"__","_") AS FileNumber
FROM (qryStmtTrustRPT LEFT JOIN tblCase ON qryStmtTrustRPT.CaseID = tblCase.CaseID) LEFT JOIN qryTrustAccount ON qryStmtTrustRPT.TrustAccountID = qryTrustAccount.TrustAccountID
ORDER BY qryStmtTrustRPT.TrustAccountID, qryTrustAccount.OrderNr;